// A struct of every scalar type and a bool, at fixed offsets without
// padding
type Packed struct {
	Int8    int8
	Uint8   uint8
	Int16   int16
	Uint16  uint16
	Int32   int32
	Uint32  uint32
	Int64   int64
	Uint64  uint64
	Float32 float32
	Float64 float64
	Bool    bool
}

// MarshalBinary returns the 43 bytes of a [Packed]: its scalars, little-endian,
// one after another. It never fails.
func (s Packed) MarshalBinary() ([]byte, error) {
	bytes := make([]byte, 43)
	s.put(bytes)
	return bytes, nil
}

// AppendBinary appends the 43 bytes of a [Packed] to bytes, as
// [Packed.MarshalBinary] writes them, and returns the extended bytes. It never
// fails.
func (s Packed) AppendBinary(bytes []byte) ([]byte, error) {
	start := len(bytes)
	bytes = append(bytes, make([]byte, 43)...)
	s.put(bytes[start:])
	return bytes, nil
}

// UnmarshalBinary reads a [Packed] from the start of bytes. It fails with a
// [*tafla.DecodeError] if bytes are shorter than 43.
func (s *Packed) UnmarshalBinary(bytes []byte) error {
	if len(bytes) < 43 {
		return &tafla.DecodeError{Kind: tafla.OutOfRange, ByteLength: 43, Available: len(bytes)}
	}

	*s = readPacked(bytes)
	return nil
}

// ReadPacked reads a [Packed] from the start of bytes and returns it, which the
// compiler can keep in registers, where [Packed.UnmarshalBinary] reads into a
// struct in memory. It fails with a [*tafla.DecodeError] if bytes are shorter
// than 43.
func ReadPacked(bytes []byte) (Packed, error) {
	if len(bytes) < 43 {
		return Packed{}, &tafla.DecodeError{Kind: tafla.OutOfRange, ByteLength: 43, Available: len(bytes)}
	}

	return readPacked(bytes), nil
}

// readPacked reads the scalars of a [Packed] from the start of bytes, which
// hold at least its 43 bytes
func readPacked(bytes []byte) Packed {
	_ = bytes[42]
	var s Packed
	s.Int8 = int8(bytes[0])
	s.Uint8 = bytes[1]
	s.Int16 = int16(binary.LittleEndian.Uint16(bytes[2:]))
	s.Uint16 = binary.LittleEndian.Uint16(bytes[4:])
	s.Int32 = int32(binary.LittleEndian.Uint32(bytes[6:]))
	s.Uint32 = binary.LittleEndian.Uint32(bytes[10:])
	s.Int64 = int64(binary.LittleEndian.Uint64(bytes[14:]))
	s.Uint64 = binary.LittleEndian.Uint64(bytes[22:])
	s.Float32 = math.Float32frombits(binary.LittleEndian.Uint32(bytes[30:]))
	s.Float64 = math.Float64frombits(binary.LittleEndian.Uint64(bytes[34:]))
	s.Bool = bytes[42] != 0
	return s
}

// put writes the scalars of a [Packed] into the start of bytes, which hold at
// least its 43 bytes
func (s *Packed) put(bytes []byte) {
	_ = bytes[42]
	bytes[0] = byte(s.Int8)
	bytes[1] = s.Uint8
	binary.LittleEndian.PutUint16(bytes[2:], uint16(s.Int16))
	binary.LittleEndian.PutUint16(bytes[4:], s.Uint16)
	binary.LittleEndian.PutUint32(bytes[6:], uint32(s.Int32))
	binary.LittleEndian.PutUint32(bytes[10:], s.Uint32)
	binary.LittleEndian.PutUint64(bytes[14:], uint64(s.Int64))
	binary.LittleEndian.PutUint64(bytes[22:], s.Uint64)
	binary.LittleEndian.PutUint32(bytes[30:], math.Float32bits(s.Float32))
	binary.LittleEndian.PutUint64(bytes[34:], math.Float64bits(s.Float64))
	bytes[42] = 0
	if s.Bool {
		bytes[42] = 1
	}
}

// Documentation of several lines.
//
// It can hold Markdown's `code spans`, non-ASCII text such as å, 世界 and
// 🦀, and text that closes a comment or string in some language: */, """,
// a backslash \ and a trailing quote"
